<template>
  <view class="feed-page">
    <scroll-view
      wx:ref="feedScroll"
      class="feed-scroll"
      scroll-y
      enhanced
      binddragstart="onDragStart"
      binddragging="onDragging"
      binddragend="onDragEnd"
    >
      <sticky-header offset-top="0">
        <view class="categories">
          <text
            wx:for="{{categories}}"
            wx:key="id"
            wx:class="{{activeCategoryId === item.id ? 'category-active' : ''}}"
            bindtap="selectCategory(item.id)"
          >{{item.name}}</text>
        </view>
      </sticky-header>
      <view class="feed-content">
        <view wx:for="{{products}}" wx:key="id" class="product">
          <image src="{{item.image}}" mode="widthFix" bindload="refreshFeedScroll" />
          <product-video
            wx:if="{{item.video}}"
            product="{{item}}"
            bindlayoutchange="refreshFeedScroll"
          />
        </view>
      </view>
    </scroll-view>
    <view class="fixed-cart" bindtap="openCart">购物车 {{cartCount}}</view>
  </view>
</template>

<script>
import mpx, { createPage } from '@mpxjs/core'

createPage({
  data: {
    categories: [],
    products: [],
    cartCount: 2,
    activeCategoryId: null
  },
  async onLoad () {
    const { data } = await mpx.request({ url: '/api/feed' })
    this.categories = data.categories
    this.products = data.products
    this.refreshFeedScroll()
  },
  methods: {
    selectCategory (categoryId) {
      this.activeCategoryId = categoryId
    },
    refreshFeedScroll () {
      if (__mpx_mode__ !== 'web') return

      this.$nextTick(() => {
        const feedScroll = this.$refs && this.$refs.feedScroll
        if (feedScroll && typeof feedScroll.refresh === 'function') {
          feedScroll.refresh()
        }
      })
    },
    onDragStart () {},
    onDragging () {},
    onDragEnd () {},
    openCart () {
      mpx.navigateTo({ url: '/pages/cart/index' })
    }
  }
})
</script>

<script type="application/json">
{
  "usingComponents": {
    "product-video": "../../components/product-video"
  }
}
</script>

<style scoped>
.feed-page, .feed-scroll { height: 100%; }
.feed-content { min-height: 100%; }
.categories { display: flex; background: #fff; }
.category-active { font-weight: 700; }
.product { padding: 24rpx; }
.fixed-cart { position: fixed; right: 24rpx; bottom: 40rpx; }
</style>
<template>
  <view class="product-video">
    <video
      id="product-video"
      src="{{product.video}}"
      autoplay
      muted@web="{{true}}"
      muted@wx="{{false}}"
      playsinline@web="{{true}}"
      enable-danmu@wx
      bindtimeupdate="onTimeUpdate"
      bindloadedmetadata="onLoadedMetadata"
      binderror="onVideoError"
    />
    <text>{{progress}} / {{duration}}</text>
  </view>
</template>

<script>
import { createComponent } from '@mpxjs/core'

createComponent({
  properties: {
    product: { type: Object, value: () => ({}) }
  },
  data: {
    progress: 0,
    duration: 0
  },
  methods: {
    onTimeUpdate (event) {
      const detail = event.detail || {}
      const target = detail.target || event.target || {}

      this.progress = typeof detail.currentTime === 'number'
        ? detail.currentTime
        : (target.currentTime || 0)
      this.duration = typeof detail.duration === 'number'
        ? detail.duration
        : (target.duration || 0)
    },
    onLoadedMetadata (event) {
      const detail = event.detail || {}
      const target = detail.target || event.target || {}
      const width = detail.width || target.videoWidth
      const height = detail.height || target.videoHeight

      if (width && height) {
        this.videoSize = `${width}x${height}`
      }
      if (typeof detail.duration === 'number') {
        this.duration = detail.duration
      } else if (target.duration) {
        this.duration = target.duration
      }

      this.$nextTick(() => {
        this.triggerEvent('layoutchange')
      })
    },
    onVideoError () {}
  }
})
</script>

<style scoped>
.product-video { width: 100%; }
</style>
